export function ProviderIcon({
  provider,
  size = 16,
  inverted = false,
}: {
  provider: string
  size?: number
  inverted?: boolean
}) {
  if (provider === 'codex') {
    return (
      <svg
        viewBox="0 0 24 24"
        width={size}
        height={size}
        fill="currentColor"
        aria-hidden="true"
      >
        <title>OpenAI</title>
        <path d={OPENAI_LOGO_PATH} />
      </svg>
    )
  }
  if (provider === 'antigravity') {
    return (
      <img
        src="/assets/google-gemini.svg"
        alt="Google Gemini"
        width={size}
        height={size}
        className="pointer-events-none block object-contain"
      />
    )
  }
  if (provider === 'qwen') {
    return (
      <img
        src="/assets/qwen.svg"
        alt="Qwen"
        width={size}
        height={size}
        className="pointer-events-none block object-contain"
      />
    )
  }
  if (provider === 'mimo') {
    return (
      <svg
        viewBox="0 0 24 24"
        width={size}
        height={size}
        fill="currentColor"
        aria-hidden="true"
        className={inverted ? 'text-pure-white' : 'text-ink'}
      >
        <title>MiMo</title>
        <path d={XIAOMI_LOGO_PATH} />
      </svg>
    )
  }
  if (provider === 'hunyuan' || provider === 'hy') {
    return (
      <svg
        viewBox="0 0 24 24"
        width={size}
        height={size}
        fill="currentColor"
        aria-hidden="true"
        className={inverted ? 'text-pure-white' : 'text-ink'}
      >
        <title>Hunyuan</title>
        <path d={HUNYUAN_LOGO_PATH} />
      </svg>
    )
  }
  if (provider === 'glm' || provider === 'zhipu') {
    return (
      <svg
        viewBox="0 0 24 24"
        width={size}
        height={size}
        fill="currentColor"
        aria-hidden="true"
        className={inverted ? 'text-pure-white' : 'text-ink'}
      >
        <title>GLM</title>
        <path d={GLM_LOGO_PATH} />
      </svg>
    )
  }
  return (
    <span
      aria-hidden="true"
      className={`text-[11px] leading-none font-bold ${
        inverted ? 'text-pure-white' : 'text-ink'
      }`}
    >
      A
    </span>
  )
}
